export const art = (kind, color, stage, extra = '') => `<svg viewBox="0 0 200 200" aria-hidden="true" class="illustration" ${extra}>${drawing(kind, color, stage)}</svg>`;
export function puzzleArt(index, count, picture = 'car') {
  const columns = 2, rows = count / 2;
  return `<svg viewBox="${(index % columns) * 100} ${Math.floor(index / columns) * (200 / rows)} 100 ${200 / rows}" aria-hidden="true" class="puzzle-image">${picture === 'car' ? drawing('car') : `<rect width="200" height="200" fill="#e7eee1"/><circle cx="167" cy="28" r="15" fill="#ecd69c"/><path d="M0 157q55-22 102 0t98-5v48H0" fill="#c9d4b6"/><g transform="translate(17 14) scale(.83)">${drawing(picture)}</g>`}</svg>`;
}
